CREATE OR REPLACE FUNCTION public.publish_listing(p jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_uid        uuid := auth.uid();
  v_listing_id uuid := (p->>'listing_id')::uuid;
  v_venture    ventures%rowtype;
  v_existing   listings%rowtype;
  v_title      text := btrim(coalesce(p->>'title', ''));
  v_desc       text := btrim(coalesce(p->>'description', ''));
  v_type       text := p->>'type';
  v_access     text := p->>'guest_access';
  v_price      numeric := (p->>'price')::numeric;
  v_guests     int := (p->>'max_guests')::int;
  v_bedrooms   int := (p->>'bedrooms')::int;
  v_beds       int := (p->>'beds')::int;
  v_baths      int := (p->>'bathrooms')::int;
  v_country    text := upper(btrim(coalesce(p->>'country', '')));
  v_region     text := btrim(coalesce(p->>'region', ''));
  v_area       text := btrim(coalesce(p->>'area', ''));
  v_street     text := btrim(coalesce(p->>'street_address', ''));
  v_lat        double precision := nullif(p->>'latitude', '')::double precision;
  v_lng        double precision := nullif(p->>'longitude', '')::double precision;
  v_vp         jsonb := p->'venture';
  v_media      uuid;
  v_path       text;
  v_i          int;
  v_listing_count int;
begin
  if v_uid is null then raise exception 'Please sign in first.'; end if;
  if v_listing_id is null then raise exception 'Missing listing id.'; end if;

  -- retry of an earlier successful call: just return it
  select * into v_existing from listings where id = v_listing_id;
  if found then
    if not exists (select 1 from ventures where id = v_existing.venture_id and admin_id = v_uid) then
      raise exception 'That listing id is already used.';
    end if;
    return jsonb_build_object('listing_id', v_existing.id, 'venture_id', v_existing.venture_id, 'is_active', v_existing.is_active);
  end if;

  -- ---- validate the listing
  if char_length(v_title) not between 8 and 60 then raise exception 'The listing title must be 8 to 60 characters.'; end if;
  if char_length(v_desc) not between 50 and 2000 then raise exception 'The description must be 50 to 2000 characters.'; end if;
  if v_type is null or v_type <> all (array['room','hotel','house','apartment','guest_house']) then raise exception 'Unknown property type.'; end if;
  if v_access is null or v_access <> all (array['entire_place','private_room']) then raise exception 'Unknown guest access type.'; end if;
  if v_price is null or v_price < 500 or v_price > 200000 then raise exception 'The price per night must be between 500 and 200,000.'; end if;
  if v_guests not between 1 and 50 or v_bedrooms not between 0 and 50 or v_beds not between 1 and 50 or v_baths not between 1 and 50 then
    raise exception 'Guests, bedrooms, beds or bathrooms are out of range.';
  end if;
  if char_length(v_country) <> 2 or char_length(v_area) not between 2 and 50 or char_length(v_region) > 50 then raise exception 'Check the country, region and area.'; end if;
  if char_length(v_street) not between 3 and 120 then raise exception 'Check the street address.'; end if;
  if jsonb_typeof(p->'photos') <> 'array' or jsonb_array_length(p->'photos') not between 3 and 10 then raise exception 'Add between 3 and 10 photos.'; end if;
  if jsonb_typeof(coalesce(p->'amenities', '[]'::jsonb)) <> 'array' or jsonb_array_length(coalesce(p->'amenities', '[]'::jsonb)) > 40 then raise exception 'Too many amenities.'; end if;

  -- ---- venture: reuse the host's, or create it (first time only)
  select * into v_venture from ventures where admin_id = v_uid;
  if not found then
    if v_vp is null then raise exception 'Please complete your venture details first.'; end if;
    if char_length(btrim(coalesce(v_vp->>'name', ''))) not between 3 and 40 then raise exception 'The venture name must be 3 to 40 characters.'; end if;
    if char_length(btrim(coalesce(v_vp->>'legal_first_name', ''))) not between 2 and 40
       or char_length(btrim(coalesce(v_vp->>'legal_last_name', ''))) not between 2 and 40 then raise exception 'Check your legal name.'; end if;
    if coalesce(v_vp->>'id_type', '') <> all (array['national_id','passport','resident_id']) or char_length(coalesce(v_vp->>'id_country', '')) <> 2 then
      raise exception 'Check your ID details.';
    end if;
    -- CHANGED 3: [+] instead of a backslash-escaped plus
    if coalesce(v_vp->>'contact_phone', '') !~ '^[+][0-9]{8,15}$' then raise exception 'Check your phone number.'; end if;

    insert into profiles (id) values (v_uid) on conflict (id) do nothing;

    insert into ventures (admin_id, venture_name) values (v_uid, btrim(v_vp->>'name')) returning * into v_venture;

    insert into host_private (user_id, contact_phone, contact_email)
    values (v_uid, v_vp->>'contact_phone', nullif(btrim(coalesce(v_vp->>'contact_email', '')), ''))
    on conflict (user_id) do update set contact_phone = excluded.contact_phone, contact_email = excluded.contact_email;

    -- only the last 4 digits are kept; the full number is checked later by the verification function
    insert into host_identity (user_id, legal_first_name, legal_last_name, id_country, id_type, id_last4)
    values (v_uid, btrim(v_vp->>'legal_first_name'), btrim(v_vp->>'legal_last_name'),
            upper(v_vp->>'id_country'), v_vp->>'id_type', right(coalesce(v_vp->>'id_last4', ''), 4))
    on conflict (user_id) do nothing;

    v_path := nullif(v_vp->>'cover_path', '');
    if v_path is not null then
      if v_path not like (v_uid::text || '/%') or position('..' in v_path) > 0 then raise exception 'Invalid cover photo path.'; end if;
      insert into media (venture_id, type, storage_path, position) values (v_venture.id, 'image', v_path, 0) returning id into v_media;
      update ventures set cover_media_id = v_media where id = v_venture.id;
    end if;
  else
    -- CHANGED 1: an existing host who is not verified yet can only have ONE listing
    select count(*) into v_listing_count from listings where venture_id = v_venture.id;
    if not v_venture.is_verified and v_listing_count >= 1 then
      raise exception 'Finish verifying your host profile before adding more listings.';
    end if;
  end if;

  -- ---- listing (public columns: only an APPROXIMATE point, rounded here, never trusted from the app)
  -- CHANGED 2: awaiting_verification = not verified (hidden until verification switches it on)
  insert into listings (id, venture_id, title, type, description, price, max_guests, bedrooms, beds, bathrooms,
                        amenities, guest_access, address, latitude, longitude, region, area, country, place_id, area_pending,
                        is_active, awaiting_verification)
  values (v_listing_id, v_venture.id, v_title, v_type, v_desc, v_price, v_guests, v_bedrooms, v_beds, v_baths,
          coalesce(p->'amenities', '[]'::jsonb), v_access, concat_ws(', ', v_area, nullif(v_region, '')),
          round(v_lat::numeric, 2), round(v_lng::numeric, 2),
          nullif(v_region, ''), v_area, v_country, nullif(p->>'place_id', '')::bigint,
          coalesce((p->>'area_is_new')::boolean, false),
          v_venture.is_verified, not v_venture.is_verified);

  -- ---- private details (exact address and exact pin)
  insert into listing_private (listing_id, street_address, building_name, unit, landmark, exact_latitude, exact_longitude)
  values (v_listing_id, v_street, nullif(btrim(coalesce(p->>'building_name', '')), ''), nullif(btrim(coalesce(p->>'unit', '')), ''),
          nullif(btrim(coalesce(p->>'landmark', '')), ''), v_lat, v_lng);

  -- ---- photos, in the order the host chose; the first one is the cover
  for v_i in 0 .. jsonb_array_length(p->'photos') - 1 loop
    v_path := p->'photos'->>v_i;
    if v_path is null or v_path not like (v_uid::text || '/%') or position('..' in v_path) > 0 then raise exception 'Invalid photo path.'; end if;
    insert into media (venture_id, type, storage_path, position) values (v_venture.id, 'image', v_path, v_i) returning id into v_media;
    insert into listing_media (listing_id, media_id, is_cover, position) values (v_listing_id, v_media, v_i = 0, v_i);
  end loop;

  -- CHANGED 3: if the host is already fully verified, this switches the listing on right now
  perform public.refresh_venture_verification(v_uid);

  return jsonb_build_object('listing_id', v_listing_id, 'venture_id', v_venture.id,
                            'is_active', (select is_active from listings where id = v_listing_id));
end $function$

CREATE OR REPLACE FUNCTION public.refresh_venture_verification(p_user uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'auth'
AS $function$
declare
  v_ok boolean;
  v_venture uuid;
begin
  select id into v_venture from ventures where admin_id = p_user;
  if v_venture is null then return; end if;

  select (u.email_confirmed_at is not null
          and u.phone_confirmed_at is not null
          and exists (select 1 from host_identity h where h.user_id = u.id and h.status = 'verified'))
    into v_ok
    from auth.users u where u.id = p_user;

  if coalesce(v_ok, false) then
    update ventures set is_verified = true where id = v_venture and not is_verified;
    -- the listings that were waiting go live now; listings a host paused themselves stay paused
    update listings set is_active = true, awaiting_verification = false
      where venture_id = v_venture and awaiting_verification;
  end if;
end $function$

CREATE OR REPLACE FUNCTION public.rls_auto_enable()
 RETURNS event_trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE
  cmd record;
BEGIN
  FOR cmd IN
    SELECT *
    FROM pg_event_trigger_ddl_commands()
    WHERE command_tag IN ('CREATE TABLE', 'CREATE TABLE AS', 'SELECT INTO')
      AND object_type IN ('table','partitioned table')
  LOOP
     IF cmd.schema_name IS NOT NULL AND cmd.schema_name IN ('public') AND cmd.schema_name NOT IN ('pg_catalog','information_schema') AND cmd.schema_name NOT LIKE 'pg_toast%' AND cmd.schema_name NOT LIKE 'pg_temp%' THEN
      BEGIN
        EXECUTE format('alter table if exists %s enable row level security', cmd.object_identity);
        RAISE LOG 'rls_auto_enable: enabled RLS on %', cmd.object_identity;
      EXCEPTION
        WHEN OTHERS THEN
          RAISE LOG 'rls_auto_enable: failed to enable RLS on %', cmd.object_identity;
      END;
     ELSE
        RAISE LOG 'rls_auto_enable: skip % (either system schema or not in enforced list: %.)', cmd.object_identity, cmd.schema_name;
     END IF;
  END LOOP;
END;
$function$
